text:
calendar-dialog-subview-manager {
  display: block;
  overflow-y: auto;

  & > *:not([hidden]) {
    block-size: 100%;
    display: flex;
    flex-direction: column;
    gap: calc(var(--space-base) + var(--space-step));
    padding-block-end: calc(var(--space-base) + var(--space-step));
  }
}
